DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_1','Substitute Classroom[NEWLINE]Timed economic choices with a risky combat surge[NEWLINE]Domination or Science; Culture through selected windows[NEWLINE][NEWLINE]Choose the Roll Call effect that supports the coming eight turns, and treat Insubordination as a real risk rather than a controllable countdown. Detention can be powerful, but arriving unprepared for it wastes the opportunity.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_2','Establish an ordinary economy and a defensible army while waiting for the first Roll Call. Decide whether the first priority is research, infrastructure or military readiness before choosing a student.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_3','Use targeted choices for an actual plan. Timothy trades the larger specialist modifier for broad output without correction risk. With other students, retain the Happiness and army readiness to handle a third correction and Detention.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_4','Coordinate a prepared force with any combat window and keep the economy useful between choices. Principal''s Offices help the empire-wide Detention Happiness cost, but building more Offices does not repeatedly reduce that penalty.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_5','- Roll Call can focus temporary benefits on several different strategic needs.[NEWLINE]- Detention rewards a prepared military force and qualifying enemy kills.[NEWLINE]- Hall Monitors combine territorial combat with a local kill-Culture role.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_6','- Choices have fixed cooldowns and do not remain active permanently.[NEWLINE]- Most named students introduce correction risk; the exact third-correction timing is not guaranteed.[NEWLINE]- Detention costs Happiness and does not substitute for an army already in position.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_7','- Avoid a decisive battle during a prepared Detention combat window.[NEWLINE]- Pressure the empire during inactive intervals and force a less convenient student choice.[NEWLINE]- Do not feed easy friendly-territory kills to Hall Monitors.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_8','- Assuming the correction outcome or Detention start can be scheduled exactly.[NEWLINE]- Choosing a military buff while the army is still travelling.[NEWLINE]- Expecting multiple Offices to reduce the global Happiness penalty multiple times.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared combat window can contest an attacking timing, especially if the Urgal commits while Detention is already active.[NEWLINE][NEWLINE]Luna Network: Timely territorial defense can punish lightly defended expansion before Luna''s infrastructure has matured.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Eternal Number Ten: Permanent career gains can keep accumulating during the gaps between classroom bonuses.[NEWLINE][NEWLINE]Terra: A planned local economic Mode can make use of the time between Garvey''s fixed temporary windows.');
