INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_BACKGROUND','Choose the Roll Call effect that supports the coming eight turns, and treat Insubordination as a real risk rather than a controllable countdown. Detention can be powerful, but arriving unprepared for it wastes the opportunity.');
