INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_STRATEGY','Choose the Roll Call effect that supports the coming eight turns, and treat Insubordination as a real risk rather than a controllable countdown. Detention can be powerful, but arriving unprepared for it wastes the opportunity.[NEWLINE][NEWLINE]Establish an ordinary economy and a defensible army while waiting for the first Roll Call. Decide whether the first priority is research, infrastructure or military readiness before choosing a student.[NEWLINE][NEWLINE]Use targeted choices for an actual plan. Timothy trades the larger specialist modifier for broad output without correction risk. With other students, retain the Happiness and army readiness to handle a third correction and Detention.[NEWLINE][NEWLINE]Coordinate a prepared force with any combat window and keep the economy useful between choices. Principal''s Offices help the empire-wide Detention Happiness cost, but building more Offices does not repeatedly reduce that penalty.');
