INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_LEADER_TEXT_2','Establish an ordinary economy and a defensible army while waiting for the first Roll Call. Decide whether the first priority is research, infrastructure or military readiness before choosing a student.[NEWLINE][NEWLINE]Use targeted choices for an actual plan. Timothy trades the larger specialist modifier for broad output without correction risk. With other students, retain the Happiness and army readiness to handle a third correction and Detention.[NEWLINE][NEWLINE]Coordinate a prepared force with any combat window and keep the economy useful between choices. Principal''s Offices help the empire-wide Detention Happiness cost, but building more Offices does not repeatedly reduce that penalty.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THESUBSTITUTECLASSROOM_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared combat window can contest an attacking timing, especially if the Urgal commits while Detention is already active.[NEWLINE][NEWLINE]Luna Network: Timely territorial defense can punish lightly defended expansion before Luna''s infrastructure has matured.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Eternal Number Ten: Permanent career gains can keep accumulating during the gaps between classroom bonuses.[NEWLINE][NEWLINE]Terra: A planned local economic Mode can make use of the time between Garvey''s fixed temporary windows.');
